import {PGlite} from './validation_runtime/package/dist/index.js';
import fs from 'node:fs/promises';import crypto from 'node:crypto';
const root='EVA_PRINT_WEBSITE_BRIEF_2026-10-02';const db=new PGlite();const checks=[];
const q=async(s,p=[])=> (await db.query(s,p)).rows;
function ok(name,value){if(!value)throw Error('FAILED: '+name);checks.push({check:name,result:'passed'});}
try{
 for(const f of ['schema.sql','002_dynamic_fields.sql','seed.sql']){await db.exec(await fs.readFile(root+'/07_DATABASE/'+f,'utf8'));console.log('Applied '+f);}
 const [counts]=await q(`SELECT (SELECT count(*) FROM materials) materials,(SELECT count(*) FROM industries) industries,(SELECT count(*) FROM locales) locales,(SELECT count(*) FROM content_fields) fields,(SELECT count(*) FROM assets) assets,(SELECT count(*) FROM supplier_sku_options) supplier_sku_options`);
 const expectedMaterials=JSON.parse(await fs.readFile(root+'/02_MATERIALS/materials.en.json')).length;
 ok('Seed imports the complete researched grade catalog, 36 industries and 7 dynamic locales',counts.materials===expectedMaterials&&counts.industries===36&&counts.locales===7);
 const [teamField]=await q("SELECT id,source_value FROM content_fields WHERE field_key='page.home.intro'");
 let tokenRejected=false;try{await q("INSERT INTO field_translations(field_id,locale_code,translated_value,source_version) VALUES($1,'de',$2::jsonb,1)",[teamField.id,JSON.stringify('A translation missing the protected count token.')]);}catch(e){tokenRejected=/preserve registered source tokens/.test(e.message);}ok('Translations cannot discard a shared fact token',tokenRejected);
 const [factsBefore]=await q('SELECT count(*) n FROM render_events');await q("UPDATE site_settings SET value='6'::jsonb WHERE setting_key='engineer_count'");const [binding]=await q("SELECT s.value FROM content_token_bindings b JOIN site_settings s ON s.setting_key=b.setting_key WHERE b.token_key='engineer_count'");const [factsAfter]=await q('SELECT count(*) n FROM render_events');ok('Shared fact edits update a canonical binding and invalidate all language views',binding.value===6&&factsAfter.n>factsBefore.n&&teamField.source_value.includes('{engineer_count}'));
 const [field]=await q("UPDATE content_fields SET publication_status='published' WHERE field_key='material.abs-fiberlogy.description' RETURNING id,source_version");
 await q("INSERT INTO field_translations(field_id,locale_code,translated_value,source_version,review_status) VALUES($1,'de',$2::jsonb,$3,'reviewed')",[field.id,JSON.stringify('Test German technical description.'),field.source_version]);
 let [resolved]=await q("SELECT * FROM resolved_fields('material','abs-fiberlogy','de') WHERE field_key='material.abs-fiberlogy.description'");ok('Current reviewed translation is resolved for its language',resolved.value==='Test German technical description.'&&!resolved.is_fallback);
 await q("UPDATE content_fields SET source_value=$2::jsonb WHERE id=$1",[field.id,JSON.stringify('Updated English technical description for validation.')]);
 const [newSource]=await q('SELECT source_version FROM content_fields WHERE id=$1',[field.id]);ok('Editing the source advances its version',newSource.source_version===2);
 const [oldTranslation]=await q("SELECT translated_value,review_status FROM field_translations WHERE field_id=$1 AND locale_code='de'",[field.id]);ok('Reviewed text is retained and marked stale',oldTranslation.review_status==='stale'&&oldTranslation.translated_value==='Test German technical description.');
 const [jobs]=await q("SELECT count(*) n FROM translation_jobs WHERE field_id=$1 AND source_version=2 AND status='queued'",[field.id]);ok('Source edit queues every other initial language',jobs.n===6);
 [resolved]=await q("SELECT * FROM resolved_fields('material','abs-fiberlogy','de') WHERE field_key='material.abs-fiberlogy.description'");ok('Stale translation falls back to the latest English source',resolved.is_fallback&&resolved.value==='Updated English technical description for validation.');
 let rejected=false;try{await q("UPDATE field_translations SET review_status='reviewed',source_version=1 WHERE field_id=$1 AND locale_code='de'",[field.id]);}catch(e){rejected=/current source version/.test(e.message);}ok('Delayed obsolete translation cannot be published',rejected);
 const [rev]=await q('SELECT count(*) n FROM field_revisions WHERE field_id=$1 AND source_version=1',[field.id]);ok('Previous source value is retained in a revision',rev.n===1);
 const [layoutBefore]=await q("SELECT layout_version FROM page_definitions WHERE id='material-detail'");await q("UPDATE page_positions SET sort_order=99 WHERE id='material-detail.main'");const [layoutAfter]=await q("SELECT layout_version FROM page_definitions WHERE id='material-detail'");ok('Changing a position advances the shared page layout version',layoutAfter.layout_version===layoutBefore.layout_version+1);
 await q("INSERT INTO locales(code,native_name,enabled,sort_order,fallback_code) VALUES('it','Italiano',true,8,'en')");const [added]=await q("SELECT count(*) n FROM translation_jobs WHERE locale_code='it'");ok('Adding a language queues existing fields without code changes',added.n>2000);
 const [eventsBefore]=await q('SELECT count(*) n FROM render_events');await q("UPDATE menu_items SET sort_order=200 WHERE id='nav-contact'");const [eventsAfter]=await q('SELECT count(*) n FROM render_events');ok('Menu changes emit durable render invalidation',eventsAfter.n>eventsBefore.n);
 const uA='11111111-1111-4111-8111-111111111111',uB='22222222-2222-4222-8222-222222222222',pA='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',pB='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
 await q("INSERT INTO users(id,email) VALUES($1,'validation-a@example.invalid'),($2,'validation-b@example.invalid')",[uA,uB]);await q("INSERT INTO projects(id,owner_user_id,title,description,intended_use) VALUES($1,$2,'Validation A','Private test','Isolation check'),($3,$4,'Validation B','Private test','Isolation check')",[pA,uA,pB,uB]);
 const files=[];for(const [i,p,u,scan]of[[0,pA,uA,'clean'],[1,pB,uB,'clean'],[2,pA,uA,'quarantined']]){const data=Buffer.from('Isolated validation document '+i),hash=crypto.createHash('sha256').update(data).digest('hex');const [f]=await q("INSERT INTO project_files(project_id,uploaded_by_user_id,original_filename,object_key,mime_type,file_extension,size_bytes,checksum_sha256,scan_status) VALUES($1,$2,'test.txt',$3,'text/plain','txt',$4,$5,$6) RETURNING id",[p,u,'validation-'+i,data.length,hash,scan]);const [b]=await q("INSERT INTO file_blobs(project_file_id,byte_length,checksum_sha256,media_type,visibility,complete) VALUES($1,$2,$3,'text/plain','private',true) RETURNING id",[f.id,data.length,hash]);await q('INSERT INTO file_blob_chunks(blob_id,chunk_index,data) VALUES($1,0,$2)',[b.id,data]);files.push({file:f.id,blob:b.id});}
 const [publicAsset]=await q("SELECT id,relative_path FROM assets WHERE kind='drawing_png' AND rights_status='eva_original' LIMIT 1");const bytes=await fs.readFile(root+'/'+publicAsset.relative_path);const [publicBlob]=await q("INSERT INTO file_blobs(asset_id,byte_length,checksum_sha256,media_type,visibility,complete) VALUES($1,$2,$3,'image/png','licensed_public',true) RETURNING id",[publicAsset.id,bytes.length,crypto.createHash('sha256').update(bytes).digest('hex')]);await q('INSERT INTO file_blob_chunks(blob_id,chunk_index,data) VALUES($1,0,$2)',[publicBlob.id,bytes]);
 const [refAsset]=await q("SELECT id FROM assets WHERE kind='photo' AND rights_status='reference_only' LIMIT 1");const [refBlob]=await q("INSERT INTO file_blobs(asset_id,byte_length,checksum_sha256,media_type,visibility,complete) VALUES($1,1,'test','image/jpeg','licensed_public',true) RETURNING id",[refAsset.id]);await q("INSERT INTO file_blob_chunks(blob_id,chunk_index,data) VALUES($1,0,decode('ff','hex'))",[refBlob.id]);
 const [itemB]=await q("INSERT INTO project_items(project_id,title,quantity) VALUES($1,'B part',1) RETURNING id",[pB]);rejected=false;try{await q('UPDATE project_files SET project_item_id=$1 WHERE id=$2',[itemB.id,files[0].file]);}catch(e){rejected=/same project/.test(e.message);}ok('Cross-project file/item relationships are rejected',rejected);
 await db.exec(`CREATE ROLE eva_validation_runtime NOLOGIN NOSUPERUSER NOBYPASSRLS;GRANT USAGE ON SCHEMA eva_print TO eva_validation_runtime;GRANT SELECT ON users,projects,project_items,project_files,assets,file_blobs,file_blob_chunks TO eva_validation_runtime;SET ROLE eva_validation_runtime;`);
 await q("SELECT set_config('app.user_id',$1,false),set_config('app.staff','false',false)",[uA]);const ownProjects=await q('SELECT id FROM projects');ok('Restricted runtime role sees only its customer project',ownProjects.length===1&&ownProjects[0].id===pA);
 const ownBytes=await q('SELECT data FROM file_blob_chunks WHERE blob_id=$1',[files[0].blob]);ok('Customer can read its clean complete document',ownBytes.length===1);
 ok('Another customer document is invisible',(await q('SELECT id FROM project_files WHERE id=$1',[files[1].file])).length===0);
 ok('Another customer binary chunks are invisible',(await q('SELECT data FROM file_blob_chunks WHERE blob_id=$1',[files[1].blob])).length===0);
 ok('Quarantined binary chunks are invisible to the customer',(await q('SELECT data FROM file_blob_chunks WHERE blob_id=$1',[files[2].blob])).length===0);
 ok('Original published public image can be streamed from DB',(await q('SELECT data FROM file_blob_chunks WHERE blob_id=$1',[publicBlob.id])).length===1);
 ok('Reference-only photo cannot become public through blob visibility alone',(await q('SELECT id FROM file_blobs WHERE id=$1',[refBlob.id])).length===0);
 await db.exec('RESET ROLE;');await q('UPDATE file_blobs SET complete=false WHERE id=$1',[files[0].blob]);await db.exec('SET ROLE eva_validation_runtime;');ok('Incomplete blobs remain unavailable',(await q('SELECT data FROM file_blob_chunks WHERE blob_id=$1',[files[0].blob])).length===0);await db.exec('RESET ROLE;');
 const report={checked_at:'2026-10-02',engine:'PostgreSQL embedded in PGlite 0.5.8, isolated in-memory validation database',scope:'Migrations, content seed, translation propagation, locale addition, layout/menu invalidation, database binary streaming records and customer RLS. Not a deployed Go website or production PostgreSQL server.',seed_counts:counts,checks,passed:checks.length};await fs.writeFile(root+'/12_VALIDATION/database-validation.json',JSON.stringify(report,null,2));console.log(JSON.stringify({passed:checks.length,counts}));
}finally{await db.close();}
